for k, (r, sup) in S.items():
    out.append(f"- **{k}** · {re.sub(r'<[^>]+>', '', r).replace('&amp;', '&')}")
    for s in sup: out.append(f"  - Hi recolza: {re.sub(r'<[^>]+>', '', s)}")
    out.append(f"  - Cita / lloc: {Q.get(k, '—')}")
open(os.path.join(HERE, "fonts.md"), "w").write("\n".join(out) + "\n")
print("fonts.md:", len(S), "fonts,", len(Q), "cites")
